# Function to extract the number of fatalities from the 'fatalities' column
def extract_fatalities(fatality_str):
    if '/' in fatality_str:
        return int(fatality_str.split('/')[0])
    elif fatality_str == 'nd':
        return 0
    else:
        return int(fatality_str)

